  id,
  name,
  framework,
  description,
  estimated_time,
  questions_count,
  icon,
  category,
  intro_title,
  intro_description,
  result_description,
  scoring_mode,
  content_version
) VALUES
  ('love-languages', 'Love Languages', 'Five Love Languages (Gary Chapman)', 'Discover how you and your partner prefer to give and receive love. Understanding these preferences can transform how you connect daily.', '8 min', 30, '❤️', 'connection', 'How do you experience love?', 'This assessment reveals your primary love language and helps you understand how you prefer to give and receive affection.', 'Your love language profile shows how you most naturally express and receive love.', 'preference', 'v2'),
  ('attachment-style', 'Attachment Style', 'Attachment Theory (Bowlby & Ainsworth)', 'Understand your attachment patterns and how they shape your relationship dynamics, emotional responses, and closeness with your partner.', '6 min', 20, '🔗', 'emotional', 'How do you connect emotionally?', 'Your attachment style influences how you seek closeness, handle anxiety, and maintain independence in relationships.', 'Your attachment style shapes how you bond and respond to intimacy.', 'quadrant', 'v2'),
  ('communication-style', 'Communication Style', 'Nonviolent Communication (Rosenberg)', 'Explore how you communicate needs, feelings, and boundaries. Learn patterns that strengthen or strain your connection.', '5 min', 15, '💬', 'communication', 'How do you express yourself?', 'Effective communication is the foundation of healthy relationships. Discover your strengths and growth areas.', 'Your communication profile reveals how you navigate conversations and connect with your partner.', 'profile', 'v2'),
  ('gottman-four-horsemen', 'Four Horsemen', 'Gottman Method', 'Identify destructive communication patterns that can damage your relationship. Learn to recognize and replace them with healthy alternatives.', '7 min', 20, '🐴', 'communication', 'Are there hidden patterns hurting your connection?', 'The Four Horsemen are criticism, contempt, defensiveness, and stonewalling. Learn if these patterns exist in your relationship.', 'Understanding these patterns helps you build healthier communication habits.', 'risk-profile', 'v2'),
  ('conflict-resolution', 'Conflict Resolution', 'Gottman Conflict Management', 'Discover your conflict resolution styles and learn how to navigate disagreements in ways that strengthen rather than strain your relationship.', '8 min', 25, '⚡', 'conflict', 'How do you handle disagreements?', 'Every couple conflicts, but it is how you navigate those moments that determines relationship health.', 'Your conflict style reveals strengths and strategies for healthier disagreements.', 'mixed-profile', 'v2'),
  ('values-alignment', 'Values Alignment', 'Acceptance & Commitment Therapy (ACT)', 'Explore shared values and life priorities. Understanding what matters most to both of you helps align your vision for the future.', '10 min', 30, '🎯', 'values', 'What truly matters to you both?', 'Shared values create shared purpose. This assessment explores where your values align and where they differ.', 'Your values profile shows areas of alignment and opportunities for deeper understanding.', 'profile', 'v2'),
  ('emotional-intelligence', 'Emotional Intelligence', 'Goleman EQ Model', 'Assess your emotional awareness, regulation, and responsiveness. High emotional intelligence is linked to stronger, more resilient relationships.', '8 min', 24, '🧠', 'emotional', 'How well do you understand and manage emotions?', 'Emotional intelligence includes recognizing your own feelings, understanding your partner, and responding thoughtfully rather than reactively.', 'Your EQ profile highlights emotional strengths and growth areas for deeper connection.', 'profile', 'v2'),
  ('intimacy-closeness', 'Intimacy & Closeness', 'Sternberg Triangular Theory', 'Measure emotional, physical, and intellectual intimacy levels. True intimacy combines all three dimensions for deep connection.', '9 min', 27, '💕', 'intimacy', 'How intimate is your connection?', 'Intimacy goes beyond physical closeness. Explore emotional vulnerability, intellectual connection, and physical affection.', 'Your intimacy profile shows the balance and depth of connection across all dimensions.', 'profile', 'v2'),
  ('trust-vulnerability', 'Trust & Vulnerability', 'Brené Brown Vulnerability Research', 'Evaluate trust levels and comfort with vulnerability. Trust is built through consistent vulnerability and emotional risk-taking.', '7 min', 18, '🛡️', 'trust', 'How safe do you feel being vulnerable?', 'Vulnerability is the foundation of deep connection. This assessment explores how comfortable you are being emotionally open.', 'Your trust profile reveals the safety and depth of emotional vulnerability in your relationship.', 'profile', 'v2'),
  ('financial-values', 'Financial Values', 'Financial Therapy Models', 'Understand your money beliefs, spending patterns, and financial communication. Financial stress is a leading cause of relationship tension.', '8 min', 22, '💰', 'values', 'How do your money values align?', 'Money is one of the most common sources of conflict in relationships. Understanding each other financial perspectives is key.', 'Your financial compatibility profile shows alignment and differences in money values and habits.', 'profile', 'v2'),
  ('sexual-compatibility', 'Sexual Compatibility', 'Sexual Health Models', 'Explore desires, boundaries, and sexual communication. Healthy sexual connection requires openness, understanding, and mutual satisfaction.', '10 min', 25, '🔥', 'intimacy', 'How aligned are your sexual needs and boundaries?', 'Sexual compatibility is about more than desire—it includes communication, comfort, and mutual respect for boundaries.', 'Your sexual compatibility profile helps identify areas of alignment and communication opportunities.', 'profile', 'v2'),
  ('shared-meaning', 'Shared Meaning', 'Gottman Sound Relationship House', 'Build shared rituals, goals, and life dreams. Creating shared meaning strengthens your bond and gives you a joint vision for the future.', '12 min', 30, '🏡', 'connection', 'What shared story are you building together?', 'Shared meaning encompasses your joint goals, traditions, and the legacy you are creating as a couple.', 'Your shared meaning profile shows the depth of your joint vision and connection.', 'profile', 'v2'),
  ('relationship-satisfaction', 'Relationship Satisfaction', 'RDAS (Revised Dyadic Adjustment Scale)', 'Overall relationship quality and satisfaction assessment. This validated scale measures consensus, satisfaction, and cohesion.', '6 min', 14, '⭐', 'general', 'How satisfied are you with your relationship?', 'This comprehensive assessment evaluates your overall relationship health across key dimensions.', 'Your satisfaction profile provides a complete picture of your relationship wellness.', 'profile', 'v2'),
  ('stress-coping', 'Stress & Coping', 'Lazarus & Folkman Stress Model', 'How you handle stress as a couple. External pressures can strain relationships or become opportunities for deeper connection.', '7 min', 20, '🌊', 'resilience', 'How do you navigate stress together?', 'Stress affects us all, and how couples support each other through challenges determines relationship resilience.', 'Your stress coping profile reveals how you and your partner handle pressure as a team.', 'profile', 'v2'),
  ('fun-personality', 'Fun & Personality', 'Leisure & Play Research', 'Explore how you enjoy time together and shared interests. Play and laughter are essential for long-term relationship satisfaction.', '6 min', 18, '🎉', 'connection', 'How do you have fun together?', 'Shared activities, humor, and play create positive experiences that strengthen your bond and create lasting memories.', 'Your fun and play profile shows how you create joy and connection through shared experiences.', 'profile', 'v2'),
  ('appreciation-gratitude', 'Appreciation & Gratitude', 'Positive Psychology', 'How you express and receive appreciation. Regular appreciation and gratitude are among the strongest predictors of relationship satisfaction.', '5 min', 15, '🙏', 'connection', 'Do you feel appreciated and grateful?', 'Expressing appreciation strengthens relationships. This assessment explores how you give and receive gratitude.', 'Your appreciation profile reveals how well gratitude and recognition flow in your relationship.', 'profile', 'v2')
ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
  framework = EXCLUDED.framework,
  description = EXCLUDED.description,
  estimated_time = EXCLUDED.estimated_time,
  questions_count = EXCLUDED.questions_count,
  icon = EXCLUDED.icon,
  category = EXCLUDED.category,
  intro_title = EXCLUDED.intro_title,
  intro_description = EXCLUDED.intro_description,
  result_description = EXCLUDED.result_description,
  scoring_mode = EXCLUDED.scoring_mode,
  content_version = EXCLUDED.content_version;

ON CONFLICT (assessment_id, dimension_key) DO UPDATE SET
  label = EXCLUDED.label,
  direction = EXCLUDED.direction,
  weight = EXCLUDED.weight,
  sort_order = EXCLUDED.sort_order;

ON CONFLICT (assessment_id, band_key) DO UPDATE SET
  min_score = EXCLUDED.min_score,
  max_score = EXCLUDED.max_score,
  title = EXCLUDED.title,
  summary = EXCLUDED.summary,
  recommendation = EXCLUDED.recommendation,
  sort_order = EXCLUDED.sort_order;

ON CONFLICT (assessment_id, question_key) DO UPDATE SET
  question_text = EXCLUDED.question_text,
  question_type = EXCLUDED.question_type,
  scale = EXCLUDED.scale,
  category = EXCLUDED.category,
  reverse = EXCLUDED.reverse,
  options = EXCLUDED.options,
  sort_order = EXCLUDED.sort_order;
